const mergedKoMessages = { ...koMessages, ...presentationKoMessages };
const mergedEnMessages = { ...enMessages, ...presentationEnMessages };

/** §28.7 ambient ticker masked nick pool — locale catalog only (presentation display props). */
export const LANDING_AMBIENT_MASKED_NICKS = [
  '김**',
  '이**',
  '박**',
  '최**',
  '정**',
  '강**',
  '조**',
  '윤**',
  '장**',
  '임**',
  '한**',
  '오**',
  '서**',
  '신**',
  '권**',
  '황**',
  '안**',
  '송**',
  '류**',
  '홍**',
] as const;

export type MessageKey = keyof typeof mergedKoMessages;
export type Locale = 'ko' | 'en';

export const messages: Record<Locale, Record<MessageKey, string>> = {
  ko: mergedKoMessages,
  en: mergedEnMessages,
};

export const DEFAULT_LOCALE: Locale = 'ko';

/**
 * Resolve a message for a locale with optional `{var}` interpolation.
 * Falls back to the key itself if missing (never throws), so a missing
 * translation is visible but non-fatal.
 */
export function translate(
  locale: Locale,
  key: MessageKey,
  vars?: Record<string, string | number>,
): string {
  const table = messages[locale] ?? messages[DEFAULT_LOCALE];
  let text: string = table[key] ?? messages[DEFAULT_LOCALE][key] ?? key;
  if (vars) {
    for (const [name, value] of Object.entries(vars)) {
      text = text.replaceAll(`{${name}}`, String(value));
    }
  }
  return text;
}
